import { RadioGroup as BaseRadioGroup } from "@base-ui/react/radio-group";
import { Radio as BaseRadio } from "@base-ui/react/radio";
import { useId, type ComponentPropsWithoutRef, type ElementType, type ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/radio.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

/**
 * Group of radios where exactly one value is chosen. Arrow keys move the
 * selection, as the ARIA radio pattern requires.
 */
export function RadioGroup({ className, ...props }: StaticClass<typeof BaseRadioGroup>) {
  return <BaseRadioGroup className={cn("eui-radio-group", className)} {...props} />;
}

export interface RadioProps extends StaticClass<typeof BaseRadio.Root> {
  label?: ReactNode;
  description?: ReactNode;
}

/** One option inside a RadioGroup. Give each one a unique `value`. */
export function Radio({ label, description, className, id, ...props }: RadioProps) {
  const generated = useId().replace(/:/g, "");
  const radioId = id ?? `eui-radio-${generated}`;
  const descriptionId = `${radioId}-description`;
  return (
    <div className="eui-choice">
      <BaseRadio.Root
        id={radioId}
        className={cn("eui-radio", className)}
        aria-describedby={description ? descriptionId : undefined}
        {...props}
      >
        <BaseRadio.Indicator className="eui-radio__indicator" />
      </BaseRadio.Root>
      {label || description ? (
        <div className="eui-choice__text">
          {label ? (
            <label htmlFor={radioId} className="eui-choice__label">
              {label}
            </label>
          ) : null}
          {description ? (
            <p id={descriptionId} className="eui-choice__description">
              {description}
            </p>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Radio. Same ring-based look as Checkbox. The dot scales in with transform only. */

.eui-radio-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.eui-radio {
  position: relative;
  flex: none;
  width: 18px;
  height: 18px;
  margin: 1px 0 0;
  padding: 0;
  border: 0;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-bg);
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-border-strong);
  cursor: pointer;
  transition: box-shadow var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-radio:hover:not(:disabled) {
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-fg-muted);
}

.eui-radio[data-checked] {
  box-shadow: 0 0 0 var(--eui-border-width) var(--eui-color-accent);
}

.eui-radio:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-radio[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.eui-radio__indicator {
  display: block;
  position: absolute;
  inset: 4px;
  border-radius: var(--eui-radius-full);
  background-color: var(--eui-color-accent);
  transform: scale(0);
  transition: transform var(--eui-duration-fast) var(--eui-easing-out);
}

.eui-radio__indicator[data-checked] {
  transform: scale(1);
}

@media (prefers-reduced-motion: reduce) {
  .eui-radio,
  .eui-radio__indicator {
    transition: none;
  }
}

/* Touch target. See choice.css; the hit area is widened without changing the look. */
.eui-radio::after {
  content: "";
  position: absolute;
  inset: -5px;
}
